alter table public.member_success_blueprints add column if not exists legacy_publications jsonb default '[]'; comment on column public.member_success_blueprints.legacy_publications is 'FRASS-0534. Lightweight pointers to book projects: [{ title, kind, publication_id }]. The manuscript lives in legacy_publications.'; create table if not exists public.legacy_publications ( id uuid primary key default gen_random_uuid(), blueprint_id uuid references public.member_success_blueprints(id) on delete set null, owner_id uuid not null references auth.users(id) on delete cascade, title text not null, kind text not null default 'new-book' check (kind in ('new-book', 'republish')), status text not null default 'outline' check (status in ('outline', 'drafting', 'editing', 'review', 'published')), chapters jsonb not null default '[]', versions jsonb not null default '[]', amendments jsonb not null default '[]', formats jsonb not null default '[]', created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); comment on table public.legacy_publications is 'FRASS-0534. A manuscript that turns a completed journey into a book. Owner-controlled; Frassy edits, never authors.'; grant select, insert, update, delete on public.legacy_publications to authenticated; grant all on public.legacy_publications to service_role; alter table public.legacy_publications enable row level security; create policy "Owners read their own manuscripts" on public.legacy_publications for select to authenticated using (owner_id = auth.uid()); create policy "Owners create their own manuscripts" on public.legacy_publications for insert to authenticated with check (owner_id = auth.uid()); create policy "Owners update their own manuscripts" on public.legacy_publications for update to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid()); create policy "Owners delete their own manuscripts" on public.legacy_publications for delete to authenticated using (owner_id = auth.uid()); create or replace function public.touch_legacy_publication() returns trigger language plpgsql security definer set search_path = public as $$ begin new.updated_at := now(); return new; end; $$; drop trigger if exists trg_touch_legacy_publication on public.legacy_publications; create trigger trg_touch_legacy_publication before update on public.legacy_publications for each row execute function public.touch_legacy_publication();